public class CommentTest {

    @Test
    public void createCommentFromDataShouldReturnValidComment() {
        Comment comment = new Comment("<!-- data -->");
        assertEquals("#comment", comment.nodeName());
        assertEquals("data", comment.getData());
    }

    @Test
    public void setDataShouldUpdateTheCommentContents() {
        Comment comment = new Comment("<!-- original data -->");
        String updatedData = "<!-- updated data -->";
        comment.setData(updatedData);
        assertEquals(updatedData, comment.getData());
    }

    @Test
    public void outerHtmlHeadShouldAppendCommentWithDataToAccumulator() {
        Appendable accum = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings();
        Comment comment = new Comment("<!-- data -->");
        comment.outerHtmlHead(accum, 0, out);
        assertEquals("<!--data-->", accum.toString());
    }

    @Test
    public void outerHtmlTailShouldNotAppendAnythingToAccumulator() {
        Appendable accum = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings();
        Comment comment = new Comment("");
        comment.outerHtmlTail(accum, 0, out);
        assertEquals("", accum.toString());
    }

    @Test
    public void toStringShouldReturnOuterHtmlStringOfComment() {
        Comment comment = new Comment("<!-- data -->");
        String expectedOutput = "<!--data-->";
        assertEquals(expectedOutput, comment.toString());
    }

